import { useCallback, useMemo, useState } from "react";
import {
  Copy,
  Gauge,
  Group,
  Moon,
  Pencil,
  Play,
  Plus,
  Redo2,
  StickyNote,
  Sun,
  Trash2,
  Undo2,
  WandSparkles,
  Ungroup,
  Workflow,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from "@/components/ui/command";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import {
  Controls,
  MiniMap,
  Weave,
  shallowArray,
  useStore,
  type Flow,
  type FlowEdge,
  type FlowNode,
} from "@/components/weave";
import { CATALOG, byKey, type CatalogItem, type Kind } from "./catalog";
import { DemoContext, nodeTypes, type PaletteTarget, type StepData } from "./nodes";
import { addNote, execute, placeNode, seedFlow, stress } from "./workflow";

const GROUPS: [Kind, string][] = [
  ["trigger", "Triggers"],
  ["action", "Actions"],
  ["logic", "Flow"],
];

export function WorkflowEditor() {
  const [flow] = useState(seedFlow);
  const [palette, setPalette] = useState<PaletteTarget | null>(null);
  const [details, setDetails] = useState<string | null>(null);
  const [running, setRunning] = useState(false);
  const [dark, setDark] = useState(() => document.documentElement.classList.contains("dark"));
  const nodeCount = useStore(flow, (s) => s.nodeIds.length);
  const edgeCount = useStore(flow, (s) => s.edges.length);
  const canUndo = useStore(flow, () => flow.canUndo);
  const canRedo = useStore(flow, () => flow.canRedo);

  const demo = useMemo(() => ({ openPalette: (t: PaletteTarget = {}) => setPalette(t), openDetails: setDetails }), []);
  const edgeToolbar = useCallback(
    (e: FlowEdge) => (
      <>
        <Button
          size="icon-xs"
          variant="ghost"
          className="pointer-coarse:size-9"
          aria-label="Insert node"
          onClick={() => setPalette({ between: e })}
        >
          <Plus />
        </Button>
        <Button
          size="icon-xs"
          variant="ghost"
          className="pointer-coarse:size-9"
          aria-label="Delete connection"
          onClick={() => flow.remove([], [e.id])}
        >
          <Trash2 />
        </Button>
      </>
    ),
    [flow],
  );

  const toggleTheme = () => setDark(document.documentElement.classList.toggle("dark"));
  const run = async () => {
    setRunning(true);
    await execute(flow);
    setRunning(false);
  };

  return (
    <DemoContext.Provider value={demo}>
      <div className="flex h-dvh flex-col bg-background text-foreground">
        <header className="flex h-14 shrink-0 items-center gap-2 border-b px-3 pt-[env(safe-area-inset-top)] sm:gap-3 sm:px-4">
          <div className="grid size-8 place-items-center rounded-lg bg-primary text-primary-foreground">
            <Workflow className="size-4" />
          </div>
          <div className="leading-tight">
            <div className="text-sm font-semibold">Lead routing</div>
            <div className="hidden text-xs text-muted-foreground sm:block">Weave · node editor</div>
          </div>
          <Badge variant="secondary" className="ml-2 hidden tabular-nums sm:inline-flex">
            {nodeCount} nodes · {edgeCount} links
          </Badge>
          <div className="ml-auto flex items-center gap-1.5">
            <Button variant="ghost" size="icon-sm" aria-label="Undo" disabled={!canUndo} onClick={() => flow.undo()}>
              <Undo2 />
            </Button>
            <Button variant="ghost" size="icon-sm" aria-label="Redo" disabled={!canRedo} onClick={() => flow.redo()}>
              <Redo2 />
            </Button>

            <Button variant="ghost" size="sm" aria-label="Add 500 nodes" onClick={() => stress(flow)}>
              <Gauge /> <span className="hidden sm:inline">Add 500</span>
            </Button>
            <Button variant="ghost" size="icon-sm" aria-label="Toggle theme" onClick={toggleTheme}>
              {dark ? <Sun /> : <Moon />}
            </Button>
            <Button
              variant="ghost"
              size="sm"
              aria-label="Tidy up"
              onClick={() => flow.layout().then(() => flow.fitView())}
            >
              <WandSparkles /> <span className="hidden sm:inline">Tidy up</span>
            </Button>
            <Button variant="ghost" size="icon-sm" aria-label="Add note" onClick={() => addNote(flow)}>
              <StickyNote />
            </Button>
            <Separator orientation="vertical" className="mx-1 h-5!" />

            <Button variant="outline" size="sm" aria-label="Add node" onClick={() => setPalette({})}>
              <Plus /> <span className="hidden sm:inline">Add node</span>
            </Button>
            <Button size="sm" onClick={run} disabled={running}>
              <Play className="fill-current" /> {running ? "Running…" : "Execute"}
            </Button>
          </div>
        </header>

        <Weave
          flow={flow}
          nodeTypes={nodeTypes}
          edgeToolbar={edgeToolbar}
          onConnectEnd={({ from }) => setPalette({ from })}
          onKeyDown={(e) => {
            if (e.key !== "Tab") return;
            e.preventDefault();
            setPalette({});
          }}
          // Theme hook: runs light up green instead of the default --primary.
          className="flex-1 [--weave-edge-flow:var(--color-emerald-500)]"
        >
          <Controls />
          <SelectionBar flow={flow} onEdit={setDetails} />
          <MiniMap className="hidden md:block" nodeColor={minimapColor} />
          <div className="pointer-events-none absolute top-4 left-4 z-30 hidden text-xs text-muted-foreground lg:block">
            Drag to pan · ⌘/pinch to zoom · Shift-drag to select · ⌫ delete · ⌘C/⌘V copy · ⌘D duplicate · ⌘G group · ⌘Z
            undo
          </div>
        </Weave>
      </div>

      <Palette flow={flow} target={palette} onClose={() => setPalette(null)} />
      <Details flow={flow} id={details} onClose={() => setDetails(null)} />
    </DemoContext.Provider>
  );
}

/** Minimap fill: the node's catalog hue (tint classes look like "bg-violet-500/12 …"). */
const minimapColor = (n: FlowNode) =>
  n.type === "note"
    ? "--color-amber-400"
    : n.type === "group"
      ? "--muted"
      : `--color-${/bg-(\w+)-500/.exec(byKey[n.data.key]?.tint ?? "")?.[1] ?? "neutral"}-500`;

/** Floating actions for the selection: touch has no Delete key or reliable double-click. */
function SelectionBar({ flow, onEdit }: { flow: Flow; onEdit: (id: string) => void }) {
  const nodes = useStore(flow, (s) => s.nodeIds.filter((id) => s.nodes[id]?.selected), shallowArray);
  const edges = useStore(flow, (s) => s.edges.filter((e) => e.selected), shallowArray);
  const total = nodes.length + edges.length;
  if (!total) return null;
  const only = nodes.length === 1 ? nodes[0] : undefined;
  const editable = only && flow.get().nodes[only]?.type === "step";
  const group = only && flow.get().nodes[only]?.type === "group" ? only : undefined;
  return (
    <div className="absolute bottom-[max(1rem,env(safe-area-inset-bottom))] left-1/2 z-30 flex -translate-x-1/2 items-center gap-1 rounded-xl border bg-card/90 p-1 pl-3 shadow-lg backdrop-blur-md animate-in fade-in-0 slide-in-from-bottom-2">
      <span className="mr-1 text-xs whitespace-nowrap text-muted-foreground tabular-nums">{total} selected</span>
      {editable && (
        <Button variant="ghost" size="sm" className="pointer-coarse:h-9" onClick={() => onEdit(only)}>
          <Pencil /> Edit
        </Button>
      )}
      {group ? (
        <Button variant="ghost" size="sm" className="pointer-coarse:h-9" onClick={() => flow.ungroup(group)}>
          <Ungroup /> <span className="hidden sm:inline">Ungroup</span>
        </Button>
      ) : (
        nodes.length > 0 && (
          <Button variant="ghost" size="sm" className="pointer-coarse:h-9" onClick={() => flow.group()}>
            <Group /> <span className="hidden sm:inline">Group</span>
          </Button>
        )
      )}
      {nodes.length > 0 && (
        <Button
          variant="ghost"
          size="sm"
          className="pointer-coarse:h-9"
          aria-label="Duplicate"

          onClick={() => flow.duplicate()}
        >
          <Copy /> <span className="hidden sm:inline">Duplicate</span>
        </Button>
      )}
      <Button
        variant="ghost"
        size="sm"
        className="text-destructive pointer-coarse:h-9"
        onClick={() => flow.removeSelected()}
      >
        <Trash2 /> Delete
      </Button>
    </div>
  );
}

/** Name matches outrank description matches (cmdk orders groups by their best item). */
const rank = (value: string, search: string, keywords: string[] = []) => {
  const q = search.toLowerCase();
  return value.toLowerCase().includes(q) ? 1 : keywords.join(" ").toLowerCase().includes(q) ? 0.5 : 0;
};

function Palette({ flow, target, onClose }: { flow: Flow; target: PaletteTarget | null; onClose: () => void }) {
  const [query, setQuery] = useState("");
  // Coming from an output (or splicing an edge) needs a node with an input; from an input, one with an output.
  const needsInput = target?.from?.type === "source" || !!target?.between;
  const items = CATALOG.filter(
    (i) => (needsInput ? i.inputs.length : true) && (target?.from?.type === "target" ? i.outputs.length : true),
  );
  // cmdk ranks items within a group but doesn't reorder groups, so search results go in one flat group.
  const groups: [string, CatalogItem[]][] = query
    ? [["Results", items]]
    : GROUPS.map(([kind, heading]) => [heading, items.filter((i) => i.kind === kind)]);
  const close = () => {
    setQuery("");
    onClose();
  };

  return (
    <CommandDialog
      open={!!target}
      onOpenChange={(o) => !o && close()}
      title="Add node"
      description="Search for a node to add"
    >
      <Command filter={rank}>
        <CommandInput placeholder="Search nodes…" value={query} onValueChange={setQuery} />
        <CommandList>
          <CommandEmpty>No nodes found.</CommandEmpty>
          {groups.map(
            ([heading, group]) =>
              group.length > 0 && (
                <CommandGroup key={heading} heading={heading}>
                  {group.map((item) => (
                    <CommandItem
                      key={item.key}
                      value={item.label}
                      keywords={[item.description]}
                      onSelect={() => {
                        flow.batch(() => placeNode(flow, item, target ?? {})); // one undo step
                        close();
                        requestAnimationFrame(() => flow.el?.focus());
                      }}
                    >
                      <div className={`grid size-7 place-items-center rounded-md ${item.tint}`}>
                        <item.icon className="size-4" />
                      </div>
                      <div className="flex flex-col">
                        <span>{item.label}</span>
                        <span className="text-xs text-muted-foreground">{item.description}</span>
                      </div>
                      {item.outputs.length > 1 && <CommandShortcut>{item.outputs.length} outputs</CommandShortcut>}
                    </CommandItem>
                  ))}
                </CommandGroup>
              ),
          )}
        </CommandList>
      </Command>
    </CommandDialog>
  );
}

function Details({ flow, id, onClose }: { flow: Flow; id: string | null; onClose: () => void }) {
  const node = useStore(flow, (s) => (id ? s.nodes[id] : undefined));
  const data = node?.data as StepData | undefined;
  const item = data && byKey[data.key];
  return (
    <Dialog open={!!item} onOpenChange={(o) => !o && onClose()}>
      {item && data && (
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <div className="flex items-center gap-3">
              <div className={`grid size-10 place-items-center rounded-lg ${item.tint}`}>
                <item.icon className="size-5" />
              </div>
              <div>
                <DialogTitle>{data.label}</DialogTitle>
                <DialogDescription>{item.description}</DialogDescription>
              </div>
            </div>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="grid gap-2">
              <Label htmlFor="node-name">Name</Label>
              <Input
                id="node-name"
                value={data.label}
                onChange={(e) => flow.updateNodeData(id!, { label: e.target.value })}
              />
            </div>
            <div className="flex items-center justify-between rounded-lg border p-3">
              <div>
                <Label htmlFor="node-disabled">Disable node</Label>
                <p className="text-xs text-muted-foreground">Skipped visually, kept in the graph.</p>
              </div>
              <Switch
                id="node-disabled"
                checked={!!data.disabled}
                onCheckedChange={(v) => flow.updateNodeData(id!, { disabled: v })}
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="destructive"
              onClick={() => {
                flow.remove([id!]);
                onClose();
              }}
            >
              <Trash2 /> Delete
            </Button>
            <Button onClick={onClose}>Done</Button>
          </DialogFooter>
        </DialogContent>
      )}
    </Dialog>
  );
}

import { createContext, useContext } from "react";
import { CircleAlert, CircleCheck, LoaderCircle, Plus, Zap } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Handle,
  type FlowEdge,
  type HandleRef,
  type HandleType,
  type NodeProps,
  type NodeTypes,
} from "@/components/weave";
import { byKey } from "./catalog";

export type StepData = { key: string; label: string; status?: "running" | "success" | "error"; disabled?: boolean };

/** Where a node picked from the palette goes: after/before a handle, or spliced into an edge. */
export type PaletteTarget = { from?: HandleRef; between?: FlowEdge };

export const DemoContext = createContext({
  openPalette: (_target: PaletteTarget = {}) => {},
  openDetails: (_id: string) => {},
});

const pct = (i: number, n: number) => `${((i + 1) / (n + 1)) * 100}%`;

function Ports({ node, ids, type }: { node: string; ids: string[]; type: HandleType }) {
  const { openPalette } = useContext(DemoContext);
  return ids.map((h, i) => (
    <Handle
      key={h}
      id={h}
      type={type}
      style={{ top: pct(i, ids.length) }}
      className={type === "target" ? "h-4 w-2 rounded-[3px]" : undefined}
    >
      {ids.length > 1 && (
        <span
          className={cn(
            "pointer-events-none absolute top-1/2 -translate-y-1/2 text-[10px] font-medium text-muted-foreground",
            type === "source" ? "right-full mr-2.5" : "left-full ml-2.5",
          )}
        >
          {h}
        </span>
      )}
      {type === "source" && (
        // n8n-style stub: unconnected outputs offer a "+" that opens the palette.
        <div className="absolute top-1/2 left-full hidden -translate-y-1/2 items-center group-data-[connected=false]/handle:flex">
          <div className="h-px w-7 bg-muted-foreground/40" />
          <button
            aria-label={`Add node after ${h}`}
            className="grid size-5 cursor-pointer place-items-center pointer-coarse:size-8 rounded-md border bg-card text-muted-foreground shadow-xs transition hover:border-primary hover:text-foreground"
            onClick={() => openPalette({ from: { node, handle: h, type: "source" } })}
          >
            <Plus className="size-3" />
          </button>
        </div>
      )}
    </Handle>
  ));
}

const STATUS = {
  running: <LoaderCircle className="size-4 animate-spin text-sky-500" />,
  success: <CircleCheck className="size-4 text-emerald-500" />,
  error: <CircleAlert className="size-4 text-destructive" />,
};

function StepNode({ id, data, selected }: NodeProps<StepData>) {
  const { openDetails } = useContext(DemoContext);
  const item = byKey[data.key];
  if (!item) return null;
  const Icon = item.icon;

  const multi = item.inputs.length > 1 || item.outputs.length > 1;
  return (
    <div
      onDoubleClick={() => openDetails(id)}
      className={cn(
        "relative flex w-64 items-center gap-3 rounded-xl border bg-card p-3 pr-4 text-card-foreground shadow-sm transition-[box-shadow,border-color,opacity,filter] hover:shadow-md",
        item.kind === "trigger" && "rounded-l-[2rem] pl-4",
        multi && "min-h-20",
        selected && "border-primary/50 ring-4 ring-primary/10",
        data.status === "running" && "weave-running",
        data.status === "success" && "border-emerald-500/50",
        data.disabled && "opacity-50 grayscale",
      )}
    >
      {item.kind === "trigger" && (
        <Zap className="absolute top-1/2 -left-2.5 size-4 -translate-y-1/2 fill-amber-400 text-amber-500" />
      )}
      <div className={cn("grid size-10 shrink-0 place-items-center rounded-lg", item.tint)}>
        <Icon className="size-5" />
      </div>
      <div className={cn("min-w-0 flex-1", item.outputs.length > 1 && "mr-6", item.inputs.length > 1 && "ml-4")}>
        <div className="truncate text-sm leading-tight font-medium">{data.label}</div>
        <div className="truncate text-xs text-muted-foreground">{item.description}</div>
      </div>
      {data.status && STATUS[data.status]}
      <Ports node={id} ids={item.inputs} type="target" />
      <Ports node={id} ids={item.outputs} type="source" />
      {item.tools && <Handle id="tools" type="target" side="bottom" className="rotate-45 rounded-[3px]" />}
    </div>
  );
}

// Notes (`type: "note"`) are built into Weave.
export const nodeTypes: NodeTypes = { step: StepNode };

import { DEFAULT_SIZE, createFlow, edge, type Flow, type FlowEdge, type FlowNode, type XY } from "@/components/weave";
import { CATALOG, byKey, type CatalogItem } from "./catalog";
import type { PaletteTarget, StepData } from "./nodes";

const step = (id: string, key: string, label: string, x: number, y: number): FlowNode<StepData> => ({
  id,
  type: "step",
  position: { x, y },
  data: { key, label },
});

export function seedFlow() {
  return createFlow(
    [
      // A group frames nodes whose `parent` is its id; drag its title bar or collapse it.
      {
        id: "digest",
        type: "group",
        position: { x: -40, y: 260 },
        size: { w: 1060, h: 180 },
        data: { title: "Nightly digest" },
      },
      {
        id: "note",
        type: "note",
        position: { x: 0, y: -260 },
        data: {
          text: "## Lead routing\n- **Drag** from a port to connect\n- Double-click a node to edit it, or a note to write\n- Hover a connection to *insert* a step\n- `Tab` opens the node palette",
        },
      },
      step("hook", "webhook", "New signup", 0, 0),
      step("enrich", "ai", "Enrich lead", 360, 0),
      step("check", "if", "Is enterprise?", 720, -8),
      step("mail", "email", "Welcome email", 1080, -120),
      step("sales", "chat", "Notify sales", 1080, 100),
      step("join", "merge", "Combine", 1440, -16),
      step("log", "db", "Log result", 1800, 0),
      { ...step("cron", "schedule", "Every morning", 0, 320), parent: "digest" },
      { ...step("rows", "db", "Fetch new rows", 360, 320), parent: "digest" },
      { ...step("sum", "code", "Summarize", 720, 320), parent: "digest" },
      step("search", "http", "Search the web", 100, 160),
    ],
    [
      edge("hook", "out", "enrich", "in"),
      edge("enrich", "out", "check", "in"),
      edge("check", "true", "sales", "in"),
      edge("check", "false", "mail", "in"),
      edge("mail", "out", "join", "a"),
      edge("sales", "out", "join", "b"),
      edge("join", "out", "log", "in"),
      edge("cron", "out", "rows", "in"),
      edge("rows", "out", "sum", "in"),
      // Per-edge appearance: a dotted "tool" connection (className styles the edge's paths).
      {
        ...edge("search", "out", "enrich", "tools"),
        kind: "tool",
        label: "tool",
        labelAt: 0.3,
        className: "[stroke-dasharray:0.01_6] [stroke-linecap:round] [--weave-edge-width:2.5px]",
      },
    ],
  );
}

const GAP = 360;

/** Adds a sticky note in the middle of the view. */
export function addNote(flow: Flow) {
  const at = flow.el
    ? flow.screenToFlow({ x: flow.el.clientWidth / 2 - 120, y: flow.el.clientHeight / 2 - 60 })
    : { x: 0, y: 0 };
  const id = Math.random().toString(36).slice(2, 10);
  flow.add([
    { id, type: "note", position: freeSpot(flow, at), data: { text: "### Note\nDouble-click to write **markdown**." } },
  ]);
  flow.select([id]);
}

/** Nodes reachable from `start` along edges, excluding `stop` (cycle-safe). */
function downstream(flow: Flow, start: string, stop: string) {
  const { edges } = flow.get();
  const seen = new Set([start]);
  for (const id of seen) for (const e of edges) if (e.source === id && e.target !== stop) seen.add(e.target);
  return [...seen];
}

/** Moves `pos` down until a node-sized box there overlaps nothing. */
function freeSpot(flow: Flow, pos: XY): XY {
  const s = flow.get();
  const m = 24;
  const hits = (y: number) =>
    Object.values(s.nodes).some(({ id, position: p }) => {
      const z = s.sizes[id] ?? DEFAULT_SIZE;
      return pos.x < p.x + z.w + m && pos.x + 256 + m > p.x && y < p.y + z.h + m && y + 64 + m > p.y;
    });
  let y = pos.y;
  for (let i = 0; i < 50 && hits(y); i++) y += 100;
  return { x: pos.x, y };
}

/** Adds a catalog node at the palette target and wires it up; returns the new node id. */
export function placeNode(flow: Flow, item: CatalogItem, { from, between }: PaletteTarget) {
  const s = flow.get();
  const id = Math.random().toString(36).slice(2, 10);
  const count = Object.values(s.nodes).filter((n) => n.data?.key === item.key).length;
  const label = count ? `${item.label} ${count + 1}` : item.label;
  // Align the new node's centre with the port it hangs off.
  const beside = (node: string, handle: string, dx: number) => {
    const p = s.nodes[node]?.position ?? { x: 0, y: 0 };
    const h = s.handles[node]?.[handle];
    return { x: p.x + dx, y: p.y + (h ? h.y - 32 : 0) };
  };

  let position = flow.el
    ? flow.screenToFlow({ x: flow.el.clientWidth / 2 - 128, y: flow.el.clientHeight / 2 - 32 })
    : { x: 0, y: 0 };
  const a = between && s.nodes[between.source],
    b = between && s.nodes[between.target];
  if (from && s.nodes[from.node]) {
    position = beside(from.node, from.handle, from.type === "source" ? GAP : -GAP);
  } else if (between && a && b) {
    // Make room like n8n: push the target's branch right when the gap can't fit another node.
    const shift = a.position.x + GAP * 2 - b.position.x;
    if (shift > 0) {
      const ids = downstream(flow, between.target, between.source);
      flow.moveNodes(Object.fromEntries(ids.flatMap((n) => (s.nodes[n] ? [[n, s.nodes[n].position]] : []))), shift, 0);
    }
    position = beside(between.source, between.sourceHandle, GAP);
  }

  const at = freeSpot(flow, position);
  flow.add([step(id, item.key, label, at.x, at.y)]);
  const input = item.inputs[0],
    output = item.outputs[0];
  if (from?.type === "source" && input) flow.connect(from, { node: id, handle: input, type: "target" });
  if (from?.type === "target" && output) flow.connect({ node: id, handle: output, type: "source" }, from);
  if (between && input && output) {
    flow.remove([], [between.id]);
    flow.connect(
      { node: between.source, handle: between.sourceHandle, type: "source" },
      { node: id, handle: input, type: "target" },
    );
    flow.connect(
      { node: id, handle: output, type: "source" },
      { node: between.target, handle: between.targetHandle, type: "target" },
    );
  }
  flow.select([id]);
  return id;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** Simulated run: walks the graph from every trigger, lighting nodes and edges level by level. */
export async function execute(flow: Flow) {
  // Run state is transient: keep it out of undo history.
  const node = (id: string, data: Partial<StepData>) => flow.untracked(() => flow.updateNodeData(id, data));
  const link = (id: string, patch: Partial<FlowEdge>) => flow.untracked(() => flow.updateEdge(id, patch));
  const s = flow.get();
  const steps = Object.values(s.nodes).filter((n) => n.type === "step");
  steps.forEach((n) => node(n.id, { status: undefined }));
  for (const e of s.edges) if (e.kind !== "tool") link(e.id, { label: undefined });

  let frontier = steps.filter((n) => byKey[n.data.key]?.kind === "trigger").map((n) => n.id);
  const seen = new Set(frontier);
  const lit: string[] = [];
  while (frontier.length) {
    frontier.forEach((id) => node(id, { status: "running" }));
    await sleep(650);
    const next: string[] = [];
    for (const id of frontier) {
      const n = flow.get().nodes[id];
      if (!n) continue;
      node(id, { status: "success" });
      for (const e of flow.get().edges) {
        if (e.source !== id || (n.data.key === "if" && e.sourceHandle === "false")) continue;
        // Edge labels follow the edge in canvas space: show how many items passed along it.
        const items = n.data.key === "db" ? 12 : 1;
        link(e.id, { animated: true, label: `${items} item${items > 1 ? "s" : ""}` });
        lit.push(e.id);
        if (seen.has(e.target)) continue;
        seen.add(e.target);
        next.push(e.target);
      }
    }
    frontier = next;
  }
  await sleep(1500);
  lit.forEach((id) => link(id, { animated: false }));
}

/** Adds a rows×cols grid of chained nodes below the current graph. */
export function stress(flow: Flow, rows = 20, cols = 25) {
  const actions = CATALOG.filter((i) => i.kind === "action");
  const y0 = flow.get().nodeIds.length ? flow.bounds().y + flow.bounds().h + 200 : 0;
  const tag = Date.now().toString(36);
  const nodes: FlowNode[] = [];
  const edges = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const id = `${tag}-${r}-${c}`;
      const item = actions[(r + c) % actions.length]!;

      nodes.push(step(id, item.key, `${item.label} ${r * cols + c + 1}`, c * GAP, y0 + r * 120));
      if (c) edges.push(edge(`${tag}-${r}-${c - 1}`, "out", id, "in"));
    }
  }
  flow.add(nodes, edges);
  requestAnimationFrame(() => requestAnimationFrame(() => flow.fitView()));
}
